package dev.eugheist.tc4modern;
import com.mojang.serialization.MapCodec;import net.minecraft.core.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.phys.BlockHitResult;
public final class DeconstructorBlock extends BaseEntityBlock {
 public static final MapCodec<DeconstructorBlock> CODEC=simpleCodec(DeconstructorBlock::new);public DeconstructorBlock(Properties p){super(p);}@Override protected MapCodec<? extends BaseEntityBlock> codec(){return CODEC;}@Override protected RenderShape getRenderShape(BlockState s){return RenderShape.MODEL;}
 @Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new DeconstructorEntity(p,s);}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level l,BlockState s,BlockEntityType<T> t){return createTickerHelper(t,BasicsContent.DECONSTRUCTOR_ENTITY.get(),DeconstructorEntity::tick);}
 @Override protected net.minecraft.world.InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player player,BlockHitResult hit){if(player instanceof net.minecraft.server.level.ServerPlayer server&&l.getBlockEntity(p) instanceof DeconstructorEntity table&&claim(table,player))server.openMenu(new net.minecraft.world.SimpleMenuProvider((id,inv,w)->new DeconstructorMenu(id,inv,net.minecraft.world.inventory.ContainerLevelAccess.create(l,p),table),s.is(BasicsContent.ADVANCED_DECONSTRUCTOR.get())?s.getBlock().getName():net.minecraft.network.chat.Component.translatable("container.decontable")));return net.minecraft.world.InteractionResult.sidedSuccess(l.isClientSide);}
 /** The advanced table delivers aspects to whoever placed it; an ownerless one (commands, old saves) is claimed by its first user. */
 static boolean claim(DeconstructorEntity table,Player player){if(table.advanced()&&table.owner==null){table.owner=player.getUUID();table.setChanged();}return true;}
 @Override public void setPlacedBy(Level l,BlockPos p,BlockState s,net.minecraft.world.entity.LivingEntity placer,net.minecraft.world.item.ItemStack stack){super.setPlacedBy(l,p,s,placer,stack);if(!l.isClientSide&&placer instanceof Player player&&l.getBlockEntity(p) instanceof DeconstructorEntity table)claim(table,player);}
 @Override protected void onRemove(BlockState s,Level l,BlockPos p,BlockState next,boolean moved){if(!s.is(next.getBlock())&&l.getBlockEntity(p) instanceof DeconstructorEntity table)net.minecraft.world.Containers.dropContents(l,p,table);super.onRemove(s,l,p,next,moved);}
}
